import{c as a,Q as n,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"SemaClaw: A Step Towards General-Purpose Personal AI Agents through Harness Engineering","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.11548","title":"SemaClaw: A Step Towards General-Purpose Personal AI Agents through Harness Engineering","arxiv_id":2604.11548,"collected_at":"2026-08-01T00:00:00.000Z","collected_by":"routine-d","domain":"Harness Engineering","pdf_path":"pdfs/2604.11548.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-01-semaclaw-personal-ai-agents-harness-engineering-2604-11548.md","filePath":"research/papers/2026-08-01-semaclaw-personal-ai-agents-harness-engineering-2604-11548.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-08-01-semaclaw-personal-ai-agents-harness-engineering-2604-11548.md"};function o(i,e,g,l,p,c){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="semaclaw-general-purpose-personal-ai-agents-through-harness-engineering" tabindex="-1">SemaClaw: General-Purpose Personal AI Agents through Harness Engineering <a class="header-anchor" href="#semaclaw-general-purpose-personal-ai-agents-through-harness-engineering" aria-label="Permalink to &quot;SemaClaw: General-Purpose Personal AI Agents through Harness Engineering&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文以 2026 年初 OpenClaw 興起、數百萬使用者開始部署個人 AI agent 為背景，指出 AI 開發方法論正從傳統 prompt engineering 轉向完整的基礎設施設計。研究處理兩個交織的挑戰：① <strong>典範演進</strong>——從 prompt/context engineering 邁向「harness engineering」，即建構完整系統把不受約束的 agent 轉化為可控、可稽核、可上生產的解決方案；② <strong>互動典範轉移</strong>——從離散的任務式互動轉向人類與 AI agent 之間持續、具情境感知的協作關係。</p><p>框架提供四項核心組件：① <strong>Agent 協調</strong>——DAG 為基礎的兩階段混合式方法論協調多 agent；② <strong>安全系統</strong>——PermissionBridge 行為安全框架控管 agent 行動；③ <strong>Context 管理</strong>——三層架構處理情境資訊；④ <strong>知識整合</strong>——agentic wiki skill 支援自動化個人知識庫建構。</p><p>核心洞見：隨著模型能力趨於平台期，差異化因素轉移至基礎設施層——即使可靠、可信賴的 agent 部署得以實現的 harness 系統。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>四項組件與本 workspace 既有設計高度平行：DAG 協調對應 <code>Workflow</code> 工具的 pipeline/parallel 原語；PermissionBridge 對應 core.md「不可逆操作永遠等確認」的權限層設計；三層 context 管理對應 <code>context-management.md</code> 的 progressive disclosure 下沉分層；agentic wiki 對應 <code>dreaming-consolidator</code> 的記憶固化機制。可作為「模型能力平台期後差異化在 harness」此一命題的外部佐證，呼應 core.md 公理「Model 可換；Body = hooks/gates/CI」。</p>',7)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
